main.css:
.ts-x-presenter-compare-html .split { gap: 40px; }
.ts-x-presenter-compare-html .head p { margin-top: 10px; }
.ts-x-presenter-compare-html .tools { display: grid; grid-template-columns: 692px 1fr; gap: 72px; align-items: start; }
.ts-x-presenter-compare-html figure { margin: 0; display: grid; gap: 12px; }
.ts-x-presenter-compare-html figcaption { font-size: 16px; line-height: 1.45; color: var(--ink-2); }
.ts-x-presenter-compare-html img { display: block; width: 100%; height: auto; border: 1px solid var(--hair); background: var(--plate); }
.ts-x-presenter-compare-html .rig { display: grid; grid-template-columns: 311px 369px; gap: 12px; align-items: start; }
.ts-x-presenter-compare-html .bar { display: grid; gap: 12px; }
